ap=argparse.ArgumentParser();ap.add_argument('--source',type=int,default=81);ap.add_argument('--windows',required=True);ap.add_argument('--linux',required=True);ap.add_argument('--recheck');ap.add_argument('--linux-h-recheck');ap.add_argument('--linux-storage-probe');args=ap.parse_args()
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p,lf=False):
    data=p.read_bytes();return hashlib.sha256(data.replace(b'\r\n',b'\n') if lf else data).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def directory(platform,run):return ROOT/'build/native'/('Design-analysis' if platform=='windows' else 'Design-analysis-linux')/'test-results'/run
