    if platform=='linux' and case=='documentation_h' and args.linux_storage_probe:
        return ROOT/'build/native/Design-analysis-linux/test-results'/args.linux_storage_probe/'files ä'
    return files(platform,run,case)
OUT.mkdir(exist_ok=True)
snapshots={str(n):load(ROOT/f'build/native/design-f1-source-{n}.json') for n in range(78,args.source+1)}
for bank in ('source_sha256_lf','foreign_sha256_lf'):
    for n,h in snapshots[str(args.source)][bank].items():assert sha(ROOT/n,True)==h,n
d=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Native F1 side-pane CSS flow, typography, border-box and example copy reveal. Not full H/whole-UI acceptance.',sources=snapshots,references={},runs=[],images=[],checks=[],article_parity=[],side_flow={},reference_geometry=[])
for name in ('h-dark.png','h-light.png','layouts.css','refinements.css','final-h.css','refinements.js','model.svg','index.html'):
    p=ROOT/'docs/visuals/f1-layouts'/name;d['references'][rel(p)]=sha(p)
specs=[(78,'windows','run-ucnvsh1i',6),(78,'linux','run-od9l9slt',6),(79,'windows','run-4y7mye7w',16),(79,'linux','run-umuqpr__',16),(80,'windows','run-ff0in44j',16),(80,'linux','run-ipyflf3d',16),(args.source,'windows',args.windows,16),(args.source,'linux',args.linux,16)]
if args.source>81:specs[6:6]=[(81,'windows','run-hwhtm2lw',16),(81,'linux','run-rvoi7exo',16)]
if args.source>82:specs[8:8]=[(82,'windows','run-m83szpnl',16),(82,'linux','run-g2fmsr4p',16)]
if args.recheck:specs.append((args.source,'windows',args.recheck,2))
if args.linux_h_recheck:specs.append((args.source,'linux',args.linux_h_recheck,1))
for source,platform,run,count in specs:
    p=directory(platform,run)/'results.json';records=load(p);assert len(records)==count,(run,'not terminal',len(records),count)
    d['runs'].append(dict(source=source,platform=platform,run=run,path=rel(p),sha256=sha(p),passed=sum(c['status']=='passed' for c in records),total=count,records=records))
for platform,run,prior in [('windows',args.windows,'run-1pkew78b'),('linux',args.linux,'run-vi5ij4r2')]:
    base=final_files(platform,run,'documentation_h');steps=load(base/'app-steps.json');output=steps[-1]['stdout']
    nav=re.findall(r'DOCUMENTATION H NAV FLOW:.*',output);context=re.findall(r'DOCUMENTATION H CONTEXT FLOW:.*',output)
    assert len(nav)==len(context)==28 and all(s.endswith('complete=1') for s in nav+context)
    d['side_flow'][platform]=dict(path=rel(base/'app-steps.json'),sha256=sha(base/'app-steps.json'),steps=steps,nav=nav,context=context)
    cases=[('documentation_h',f'docs-h-{n:02}.bmp',label) for n,label in ((0,'h-dark'),(16,'h-light'),(4,'reader-32'),(48,'ui-22-dark'),(52,'ui-22-light'))]
    cases.extend([('documentation_h','docs-h-example-c.bmp','example-c'),('documentation_h','docs-h-example-physim.bmp','example-physim'),('documentation_panes','docs-panes-05.bmp','example-ui-22')])
    for case,name,label in cases:
        source=final_files(platform,run,case)/'workflow ä'/name;target=OUT/f'{platform}-{label}.png';im=Image.open(source).convert('RGB');im.save(target)
        assert im.tobytes()==Image.open(target).convert('RGB').tobytes()
        d['images'].append(dict(path=rel(target),sha256=sha(target),source=rel(source),source_sha256=sha(source),rgb_sha256=hashlib.sha256(im.tobytes()).hexdigest(),size=im.size))
    for theme in ('dark','light'):
        for kind,tool in [('title','check_f1_article_title.py'),('surfaces','check_f1_h_reference.py')]:
            p=OUT/f'{platform}-{kind}-{theme}.json';command=[sys.executable,str(ROOT/'tests'/tool),'--native',str(OUT/f'{platform}-h-{theme}.png'),'--theme',theme,'--report',str(p)]
            result=subprocess.run(command,capture_output=True,text=True);check=load(p);assert result.returncode in (0,1)
            if platform=='windows' or kind=='surfaces':assert result.returncode==0,result.stdout+result.stderr
            d['checks'].append(dict(platform=platform,kind=kind,theme=theme,command=command,exit_code=result.returncode,path=rel(p),sha256=sha(p),result=check))
        ref=Image.open(ROOT/f'docs/visuals/f1-layouts/h-{theme}.png').convert('RGB');native=Image.open(OUT/f'{platform}-h-{theme}.png').convert('RGB')
        color=(38,86,153) if theme=='dark' else (192,214,247);accent=(100,170,255) if theme=='dark' else (0,73,163)
        spans=[]
        for im,ox,oy in ((ref,1,35),(native,0,0)):
            ys=[y for y in range(220,290) if im.getpixel((225+ox,y+oy))==color];assert ys
            checks=[im.getpixel((x+ox,258+oy))==accent for x in (15,16,17)]
            checks.extend((im.getpixel((233+ox,258+oy))==color,im.getpixel((234+ox,258+oy))!=color))
            spans.append(dict(vertical_span=[min(ys),max(ys)+1],edge_checks=checks,accent_rgb=[im.getpixel((x+ox,258+oy)) for x in (15,16,17)],origin=[ox,oy]))
        passed=spans[0]['vertical_span']==spans[1]['vertical_span']==[240,277] and all(all(x['edge_checks']) for x in spans)
        d['reference_geometry'].append(dict(platform=platform,theme=theme,kind='topic-row',scope='Shared active topic row: vertical flat fill, three-pixel accent and right edge; no whole-image/font/corner equivalence.',samples=spans,passed=passed,vertical_and_right_edges_match=spans[0]['vertical_span']==spans[1]['vertical_span']==[240,277] and all(all(x['edge_checks'][3:]) for x in spans)))
        tabs=[]
        for im,border,rows in ((ref,ref.width-251,(139,140)),(native,native.width-250,(104,105))):
            bands=[]
            for y in rows:
                xs=[x for x in range(border,border+230) if im.getpixel((x,y))==accent]
                bands.append([min(xs)-border,max(xs)+1-border] if xs else None)
            tabs.append(dict(bands=bands,rows=list(rows),pane_border=border))
        passed=tabs[0]['bands']==tabs[1]['bands']==[[13,51],[13,51]]
        d['reference_geometry'].append(dict(platform=platform,theme=theme,kind='model-tab',samples=tabs,passed=passed,scope='Two solid underline rows relative to the pane border; text-shaped width remains font-dependent.'))
    old=load(files(platform,prior,'documentation_h')/'app-steps.json')[-1]['stdout']
    for index in range(56):
        crops=[];paths=[];regions=[]
        for r,out in ((prior,old),(run,output)):
            line=re.search(r'DOCUMENTATION H GEOMETRY: case='+str(index)+r' .*',out)[0]
            x,w=map(float,re.search(r'article=([\d.]+),([\d.]+)',line).groups());h=float(re.search(r'body=[\d.]+,([\d.]+)',line)[1]);box=[int(x),60,int(x+w),int(60+h)]
            p=(files(platform,r,'documentation_h') if r==prior else final_files(platform,r,'documentation_h'))/'workflow ä'/f'docs-h-{index:02}.bmp';im=Image.open(p).convert('RGB');part=im.crop(box)
            crops.append(hashlib.sha256(part.tobytes()).hexdigest());paths.append(rel(p));regions.append(box)
        d['article_parity'].append(dict(platform=platform,case=index,source_versions=[77,args.source],paths=paths,regions=regions,rgb_sha256=crops,equal=crops[0]==crops[1]))
d['final_unique_scope']={}
if args.linux_storage_probe:
    p=ROOT/'build/native/Design-analysis-linux/test-results'/args.linux_storage_probe/'result.json';probe=load(p)
    assert probe['binary']['sha256']==sha(ROOT/'build/native/Design-analysis-linux/bin/physim')
    assert probe['app_deadline_seconds']==60 and probe['storage_only_change']
    d['storage_probe']=dict(source=args.source,path=rel(p),sha256=sha(p),record=probe,interpretation='Same binary and full H checker, different output filesystem. One sequential observation supports a storage effect; not an isolated causal proof or an application speedup.')
for platform in ('windows','linux'):
    records=[c for run in d['runs'] if run['source']==args.source and run['platform']==platform for c in run['records']]
    positive=sorted({c['name'] for c in records if c['status']=='passed'})
    if platform=='linux' and args.linux_storage_probe and probe['status']=='passed':positive=sorted(set(positive)|{probe['name']})
    p=ROOT/'build/native'/('Design-analysis' if platform=='windows' else 'Design-analysis-linux')/'bin'/('physim.exe' if platform=='windows' else 'physim')
    for c in records:
        for step in c.get('steps',[]):
            if step.get('target')=='physim':assert step['sha256']==sha(p)
    d['final_unique_scope'][platform]=dict(groups=positive,count=len(positive),binary=dict(path=rel(p),sha256=sha(p)))
d['build_logs']=[dict(path=rel(p),sha256=sha(p)) for p in sorted((ROOT/'build/native').glob('f1-*.log')) if re.search(r'-(?:78|79|80|81|82|83)(?:-|\.)',p.name) and 'wm' not in p.name]
d['execution']={
 'windows_command':[sys.executable,'tools/build.py','--config','Debug','--sanitizers','--build-dir','build/native/Design-analysis','--jobs','4','--test-display','--test-filter','documentation_h','documentation_detail','documentation_sidebar','documentation_navigation','documentation_keyboard','documentation_scroll','documentation_window','documentation_history','documentation_panes','documentation_math','documentation_inline_math','documentation_zoom','documentation_density','documentation_font_demand','documentation_inline','documentation_typeset'],
